// ficheiro: carrinho.js
export function calcularTotal(itens) {
  if (!Array.isArray(itens)) {
    throw new TypeError("itens deve ser um array");
  }
  return itens.reduce((total, item) => total + item.preco * item.quantidade, 0);
}

