function calcularMedia(notas) {
  let soma = 0;
  for (let i = 0; i < notas.length; i++) {
    soma += notas[i];
  }

  const media = soma / notas.length;
  console.assert(
    media >= 0 && media <= 20,
    `Média fora do intervalo esperado (0-20): ${media}`
  );
  return media;
}

console.log(calcularMedia([15, 12, 18, 9])); // 13.5

