  assert.equal(resultado, false);
});

test("rejeita um email com @ mas sem ponto no domínio", () => {
  const resultado = validarEmail("ana@exemplo");
  assert.equal(resultado, false);
});

// ficheiro: validador.js
export function validarEmail(email) {
  const partes = email.split("@");
  if (partes.length !== 2) {
    return false;
  }

  const [, dominio] = partes;
  return dominio.includes(".") && dominio.indexOf(".") > 0;
}

