import { test } from "node:test";
import assert from "node:assert/strict";
import { processarCompra } from "./carrinho.js";

test("processa a compra com sucesso e chama o pagamento com o total correto", () => {
  // Arrange
  const carrinho = [
    { preco: 20, quantidade: 2 },
    { preco: 5, quantidade: 4 },
  ];
  let valorRecebido = null;
  const pagamentoAprovadoFalso = (valor) => {
    valorRecebido = valor;
    return true;
  };

  // Act
  const resultado = processarCompra(carrinho, pagamentoAprovadoFalso);

  // Assert
  assert.equal(valorRecebido, 60);
  assert.deepEqual(resultado, { sucesso: true, total: 60 });
});

test("lança erro quando o pagamento é recusado", () => {
  const carrinho = [{ preco: 10, quantidade: 1 }];
  const pagamentoRecusadoFalso = () => false;

  assert.throws(
    () => processarCompra(carrinho, pagamentoRecusadoFalso),
    /Pagamento recusado/
  );
});

// ficheiro: carrinho.js
export function processarCompra(carrinho, processarPagamento) {
  const total = carrinho.reduce(
    (soma, item) => soma + item.preco * item.quantidade,
    0
  );

  const aprovado = processarPagamento(total);
  if (!aprovado) {
    throw new Error("Pagamento recusado");
  }

  return { sucesso: true, total };
}
